contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "T >= 1 and T <= 10",
      "description": "The number of test cases T is between 1 and 10 inclusive."
    },
    {
      "id": "P2",
      "expression": "all(1 <= H <= 1000 and 1 <= W <= 1000 and 1 <= N <= 200 for H, W, N in test_cases)",
      "description": "For each test case, grid dimensions H, W and particle count N satisfy the given bounds."
    },
    {
      "id": "P3",
      "expression": "all(all(abs(h) <= 1000 for h in row) for row in grid_rows)",
      "description": "All grid cell values h_{i,j} have absolute value at most 1000."
    },
    {
      "id": "P4",
      "expression": "all(1 <= y <= H and 1 <= x <= W and 1 <= abs_p <= 100 for y, x, abs_p in particles)",
      "description": "For each particle, coordinates are within grid bounds and absolute value is at most 100."
    },
    {
      "id": "P5",
      "expression": "len(set((y, x) for y, x, _ in particles)) == len(particles)",
      "description": "No two particles are located in the same cell."
    },
    {
      "id": "P6",
      "expression": "sum(H * W for H, W, _ in test_cases) <= 10**6",
      "description": "The sum of H*W over all test cases does not exceed 10^6."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(output_lines) == 2 * T",
      "description": "The output contains exactly 2 lines per test case."
    },
    {
      "id": "Q2",
      "expression": "all(max_V == int(output_lines[2*k]) and len(signs) == N and all(s in (1, -1) for s in signs) for k, (max_V, signs) in enumerate(zip(output_lines[0::2], [list(map(int, output_lines[2*k+1].split())) for k in range(T)])))",
      "description": "For each test case, the first line is an integer representing the maximum value V, and the second line contains N integers, each being 1 or -1."
    },
    {
      "id": "Q3",
      "expression": "all(computed_V == max_V for max_V, computed_V in zip([int(output_lines[2*k]) for k in range(T)], [sum(p_i * h_val for p_i, h_val in zip(p_vals, h_vals)) + sum(p_i * p_j for (p_i, p_j) in adj_pairs) for p_vals, h_vals, adj_pairs in zip(computed_p_vals_list, h_vals_list, adj_pairs_list)]))",
      "description": "The reported maximum value equals the value V computed using the chosen signs, where V is the sum of p_i * h_{y_i,x_i} for all particles plus the sum of p_i * p_j for all adjacent particle pairs."
    },
    {
      "id": "Q4",
      "expression": "all(computed_V >= alt_V for computed_V, alt_V in zip([int(output_lines[2*k]) for k in range(T)], [max([sum(p_i * h_val for p_i, h_val in zip(p_vals, h_vals)) + sum(p_i * p_j for (p_i, p_j) in adj_pairs) for p_vals in all_sign_combinations]) for all_sign_combinations, h_vals, adj_pairs in zip(all_sign_combinations_list, h_vals_list, adj_pairs_list)]))",
      "description": "The reported value is the maximum possible value of V achievable by any choice of signs for the particles."
